import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.ifFCyy4k.js";const p=JSON.parse('{"title":"使用說明與學習路線","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"start/usage.md","lastUpdated":1793016282000}'),h={name:"index.md"};function o(i,t,l,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="使用說明與學習路線" tabindex="-1">使用說明與學習路線 <a class="header-anchor" href="#使用說明與學習路線" aria-label="Permalink to &quot;使用說明與學習路線&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 硬體自我檢測的查詢指令未實機驗證; 硬體等級 E, F 的規格門檻待 K3 定義</li></ul></div><p><strong>結論</strong>: 本手冊以一張<a href="/lanai-handbook/start/map">架構圖</a>為終點, 分四部帶讀者走到那裡: 第一部講懂每個元件背後的原理, 第二部一次組裝一個模組, 第三部用範例說明組好的系統能解決什麼問題, 第四部是長期維運. 先選一條學習路線, 再依路線閱讀.</p><p>本手冊整理如何在自己的機器或機房內執行 AI 模型. 手冊不預設地端優於雲端, 也不包含法規解讀; 涉及法規的決定, 請洽法律顧問.</p><h2 id="全書結構" tabindex="-1">全書結構 <a class="header-anchor" href="#全書結構" aria-label="Permalink to &quot;全書結構&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部</th><th>內容</th><th>讀完能做到</th></tr></thead><tbody><tr><td><a href="/lanai-handbook/start/map">架構地圖</a></td><td>最終要組出的系統, 以及每一塊由哪個模組組裝</td><td>知道自己需要哪幾塊</td></tr><tr><td>第一部 底層知識 (K1 至 K6)</td><td>模型, 量化, 硬體, 授權, 工具呼叫, 安全</td><td>看懂圖上每個方塊在做什麼, 為什麼要這樣分區</td></tr><tr><td>第二部 模組化組裝 (M0 至 M9)</td><td>由下往上, 每章組裝一個模組, 附驗收測試</td><td>一步一步把系統架起來</td></tr><tr><td>第三部 應用範例 (P1 至 P3, E1 至 E4)</td><td>個人與企業的常見用途</td><td>知道組好的系統怎麼用在日常工作</td></tr><tr><td>第四部 維運 (O1 至 O3)</td><td>備份, 版本鎖定, 安全公告</td><td>讓系統長期安全運作</td></tr></tbody></table><p>另有<a href="/lanai-handbook/decide/summary">決策參考</a> (該不該自架, 成本, 風險) 與延伸主題<a href="/lanai-handbook/train/t1-decide">訓練微調</a>.</p><h2 id="先回答三個問題" tabindex="-1">先回答三個問題 <a class="header-anchor" href="#先回答三個問題" aria-label="Permalink to &quot;先回答三個問題&quot;">​</a></h2><table tabindex="0"><thead><tr><th>問題</th><th>選項</th></tr></thead><tbody><tr><td>1. 想做什麼</td><td>a. 自己用 / b. 給 2 人以上共用 / c. 還在評估該不該自架 / d. 想訓練或微調</td></tr><tr><td>2. 手上是什麼硬體</td><td>見下方「硬體自我檢測」, 對應等級 A 至 F</td></tr><tr><td>3. 之後誰維運</td><td>有人每週檢查安全公告與備份 / 沒有固定的人</td></tr></tbody></table><p>第 3 題的答案會限制能組到哪裡: 沒有人固定維運時, 只組到里程碑 1 (M0 至 M2).</p><h2 id="選一條學習路線" tabindex="-1">選一條學習路線 <a class="header-anchor" href="#選一條學習路線" aria-label="Permalink to &quot;選一條學習路線&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路線</th><th>閱讀順序</th><th>終點</th></tr></thead><tbody><tr><td>a. 個人路線</td><td>架構地圖 → K1, K2, K3 → M0 (單機做法) → M1 → M2 → 需要問文件時加 M4 → 範例 P1 至 P3 → O1, O2</td><td>里程碑 1, 視需要加檢索</td></tr><tr><td>b. 企業路線</td><td>架構地圖 → K1 至 K6 → M0 至 M6 (里程碑 2) → 有人每週維運時再加 M7 至 M9 (里程碑 3) → 範例 E1 至 E4 → O1 至 O3</td><td>里程碑 2 或 3</td></tr><tr><td>c. 決策者路線</td><td>決策參考整組頁面 → 架構地圖</td><td>判斷要不要投入, 投入到哪個里程碑</td></tr><tr><td>d. 訓練或微調</td><td>T1 (先判斷是否需要) → T2</td><td>多數需求用提示與檢索即可, 見 T1</td></tr></tbody></table><p>每個模組章都依同一個格式撰寫: 這一塊在圖上的位置, 前置模組, 安裝步驟, 驗收測試, 完成後的狀態. 組完一章再進下一章, 遇到問題時比較容易找出是哪一塊出錯.</p><h2 id="硬體自我檢測" tabindex="-1">硬體自我檢測 <a class="header-anchor" href="#硬體自我檢測" aria-label="Permalink to &quot;硬體自我檢測&quot;">​</a></h2><h3 id="查出自己的規格" tabindex="-1">查出自己的規格 <a class="header-anchor" href="#查出自己的規格" aria-label="Permalink to &quot;查出自己的規格&quot;">​</a></h3><p>以下指令未實機驗證, 輸出欄位名稱會因作業系統版本而異; 若與說明不符, 以系統設定畫面為準.</p><table tabindex="0"><thead><tr><th>系統</th><th>指令</th><th>看什麼</th></tr></thead><tbody><tr><td>Windows 或 Linux, 有 NVIDIA 顯示卡</td><td><code>nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv</code></td><td>顯示卡型號, 顯示記憶體, 驅動版本</td></tr><tr><td>macOS</td><td><code>system_profiler SPHardwareDataType</code></td><td>晶片 (是否為 Apple Silicon) 與記憶體</td></tr><tr><td>Linux</td><td><code>free -h</code></td><td>系統記憶體</td></tr><tr><td>Windows (PowerShell)</td><td><code>Get-CimInstance Win32_ComputerSystem | Select-Object TotalPhysicalMemory</code></td><td>系統記憶體 (單位為位元組)</td></tr></tbody></table><h3 id="對應等級" tabindex="-1">對應等級 <a class="header-anchor" href="#對應等級" aria-label="Permalink to &quot;對應等級&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等級</th><th>特徵</th><th>建議起點</th></tr></thead><tbody><tr><td>A</td><td>無獨立顯示卡的筆電</td><td>里程碑 1, 桌面版介面 (見組裝總覽的硬體對應)</td></tr><tr><td>B</td><td>8 至 12GB 顯示記憶體</td><td>里程碑 1</td></tr><tr><td>C</td><td>Apple Silicon Mac, 以統一記憶體容量決定能力</td><td>16GB 組到里程碑 1; 32GB 以上可組到里程碑 2</td></tr><tr><td>D</td><td>16GB 顯示記憶體</td><td>里程碑 2</td></tr><tr><td>E</td><td>預算較高的單機配置</td><td>里程碑 2 (規格門檻待 K3 定義)</td></tr><tr><td>F</td><td>預算更高的多卡或大容量配置</td><td>里程碑 3 (須有人每週維運)</td></tr></tbody></table><p>顯示記憶體 (或統一記憶體) 比運算速度更常決定「模型跑不跑得起來」, 估算方法見 K2. 此對應表來自研究 1 的分級, 待以第一手報價與規格核對 (信心: 中).</p><h2 id="決策者-先看這幾頁" tabindex="-1">決策者: 先看這幾頁 <a class="header-anchor" href="#決策者-先看這幾頁" aria-label="Permalink to &quot;決策者: 先看這幾頁&quot;">​</a></h2><p>不需要先懂技術, 也能判斷該不該自架. 建議順序如下:</p><ol><li><a href="/lanai-handbook/decide/summary">一頁決策摘要</a>: 三分鐘看完結論與前提.</li><li><a href="/lanai-handbook/decide/should-self-host">該不該自架決策樹</a>: 依資料敏感度, 使用人數與維運能力判斷.</li><li><a href="/lanai-handbook/decide/tco">成本試算表</a>: 自己填入數字, 比較自架與雲端 API.</li><li><a href="/lanai-handbook/decide/risk-checklist">風險自評</a>: 十個問題, 看維運前提是否成立.</li><li><a href="/lanai-handbook/decide/license-flags">授權紅旗</a>: 對外提供服務前, 哪些授權條款要先處理.</li><li><a href="/lanai-handbook/decide/poc-30days">30 天 PoC 計畫</a>: 用最小代價驗證, 再決定是否投入.</li></ol><h2 id="標示的讀法" tabindex="-1">標示的讀法 <a class="header-anchor" href="#標示的讀法" aria-label="Permalink to &quot;標示的讀法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>標示</th><th>意義</th></tr></thead><tbody><tr><td>● 必要</td><td>所有讀者都需要</td></tr><tr><td>○ 依情境</td><td>符合條件才讀, 條件寫在章首</td></tr><tr><td>◇ 進階或選讀</td><td>初階讀者可以略過</td></tr><tr><td>撰寫中 (僅有大綱)</td><td>只有章節骨架, 尚無可用內容</td></tr><tr><td>可閱讀 (部分資料待核對)</td><td>內容可參考, 但標示「待核對」的數字或來源尚未以第一手資料確認</td></tr><tr><td>已審閱</td><td>內容與來源經人工逐項核對</td></tr><tr><td>未實機驗證</td><td>指令依官方文件整理, 尚未在實機執行; 執行前請先在測試環境試跑</td></tr><tr><td>信心: 高 / 中 / 低</td><td>超出事實的判斷所附的信心水準; 標「推論」者為整理者推論</td></tr></tbody></table><p>正文只寫原則與判斷流程. 版本號, CVE, 價格與基準分數一律放在<a href="/lanai-handbook/ref/versions">參考資料</a>, 並標示來源與資料基準日.</p><h2 id="各章完成度" tabindex="-1">各章完成度 <a class="header-anchor" href="#各章完成度" aria-label="Permalink to &quot;各章完成度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>範圍</th><th>狀態</th></tr></thead><tbody><tr><td>使用說明, 架構地圖, 組裝總覽</td><td>可閱讀 (部分資料待核對)</td></tr><tr><td>K1 至 K6</td><td>可閱讀 (部分資料待核對)</td></tr><tr><td>M0 至 M3, M7 至 M9</td><td>可閱讀 (指令未實機驗證)</td></tr><tr><td>M4 至 M6</td><td>可閱讀 (部分資料待核對, 指令未實機驗證)</td></tr><tr><td>應用範例</td><td>可閱讀 (部分資料待核對, 未實機驗證)</td></tr><tr><td>O1, O2</td><td>可閱讀 (指令未實機驗證)</td></tr><tr><td>O3</td><td>可閱讀 (部分資料待核對)</td></tr><tr><td>T1 至 T3</td><td>撰寫中 (僅有大綱)</td></tr><tr><td>決策參考</td><td>可閱讀 (數字為試算框架, 非市場資料)</td></tr></tbody></table><p>全書指令與設定範例都依官方文件整理, 尚未在實機執行. 各頁「待查證」欄列出尚未查證的事項.</p>',29)])])}const u=d(h,[["render",o]]);export{p as __pageData,u as default};
